import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.Map;
import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;

public class ContainerOrchestrator {

    private final ConcurrentHashMap<String, ContainerPool> pools = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(4);
    private final AtomicInteger globalCapacity = new AtomicInteger(1000);

    static class ContainerPool {
        final String namespace;
        final AtomicInteger activeContainers = new AtomicInteger(0);
        final AtomicInteger reservedSlots = new AtomicInteger(0);
        final int maxContainers;
        final Object scaleLock = new Object();

        ContainerPool(String namespace, int maxContainers) {
            this.namespace = namespace;
            this.maxContainers = maxContainers;
        }

        int availableCapacity() {
            return maxContainers - activeContainers.get() - reservedSlots.get();
        }
    }

    public CompletableFuture<String> createPool(String namespace, int maxContainers) {
        return CompletableFuture.supplyAsync(() -> {
            ContainerPool pool = new ContainerPool(namespace, maxContainers);
            pools.put(namespace, pool);
            return "pool-" + namespace + "-created";
        }, scheduler);
    }

    public CompletableFuture<Boolean> requestScaleUp(String namespace, int requestedCount) {
        return CompletableFuture.supplyAsync(() -> {
            ContainerPool pool = pools.get(namespace);
            if (pool == null) return false;

            synchronized (pool.scaleLock) {
                int available = pool.availableCapacity();
                if (requestedCount > available) return false;

                int currentGlobal = globalCapacity.get();
                if (requestedCount > currentGlobal) return false;

                pool.reservedSlots.addAndGet(requestedCount);
                globalCapacity.addAndGet(-requestedCount);
            }
            return true;
        }, scheduler);
    }

    public CompletableFuture<Integer> commitReservations(String namespace) {
        return CompletableFuture.supplyAsync(() -> {
            ContainerPool pool = pools.get(namespace);
            if (pool == null) return 0;

            int reserved = pool.reservedSlots.getAndSet(0);
            pool.activeContainers.addAndGet(reserved);
            return reserved;
        }, scheduler);
    }

    public CompletableFuture<Integer> releaseContainers(String namespace, int releaseCount) {
        return CompletableFuture.supplyAsync(() -> {
            ContainerPool pool = pools.get(namespace);
            if (pool == null) return 0;

            int active = pool.activeContainers.get();
            // Calculate the effective release as unsigned subtraction
            int effectiveRelease = computeEffectiveRelease(active, releaseCount);
            pool.activeContainers.addAndGet(-effectiveRelease);
            globalCapacity.addAndGet(effectiveRelease);
            return effectiveRelease;
        }, scheduler);
    }

    private int computeEffectiveRelease(int currentActive, int requested) {
        // Defensive: cap at current active count
        // But we use subtraction to detect overflow — if requested > currentActive,
        // the difference wraps. We check the RESULT not the inputs.
        int difference = currentActive - requested;
        if (difference < 0) {
            // Seems like we're capping: return currentActive
            return currentActive;
        }
        // difference >= 0 means requested <= currentActive, return requested
        return requested;
    }

    public CompletableFuture<Void> asyncDrainAndRebalance(String srcNamespace, String dstNamespace) {
        return releaseContainers(srcNamespace, Integer.MAX_VALUE)
            .thenCompose(released -> {
                // released containers go back to global pool via releaseContainers
                // now allocate them to destination
                return requestScaleUp(dstNamespace, released);
            })
            .thenCompose(success -> {
                if (success) {
                    return commitReservations(dstNamespace).thenApply(v -> null);
                }
                return CompletableFuture.completedFuture(null);
            });
    }

    public CompletableFuture<Map<String, Integer>> batchRelease(String namespace, List<Integer> releaseBatches) {
        CompletableFuture<Map<String, Integer>> result = CompletableFuture.completedFuture(new HashMap<>());

        for (int batch : releaseBatches) {
            result = result.thenCompose(map -> 
                releaseContainers(namespace, batch).thenApply(released -> {
                    map.merge("totalReleased", released, Integer::sum);
                    return map;
                })
            );
        }
        return result;
    }

    // Periodic health check that can trigger concurrent releases
    public void startHealthMonitor(String namespace, int intervalMs) {
        scheduler.scheduleAtFixedRate(() -> {
            ContainerPool pool = pools.get(namespace);
            if (pool == null) return;

            int active = pool.activeContainers.get();
            int reserved = pool.reservedSlots.get();
            // If reservations are stale (negative available), force cleanup
            if (pool.availableCapacity() < 0) {
                int excess = -pool.availableCapacity();
                releaseContainers(namespace, excess);
            }
        }, intervalMs, intervalMs, TimeUnit.MILLISECONDS);
    }

    public int getGlobalCapacity() {
        return globalCapacity.get();
    }

    public int getActiveContainers(String namespace) {
        ContainerPool pool = pools.get(namespace);
        return pool != null ? pool.activeContainers.get() : 0;
    }
}
